mod lexer;
mod parser;
mod ast;
mod compiler;
mod error;
mod cli;
mod repl;

use std::io::{self, Read, Write, IsTerminal};
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    let bin_name = args.get(0).cloned().unwrap_or_else(|| "executable".to_string());
    let bin_name_only = std::path::Path::new(&bin_name)
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("executable")
        .to_string();
    let config = match cli::parse_args(&args[1..], &bin_name_only) {
        Ok(c) => c,
        Err(cli::CliError::Help(msg)) => {
            print!("{}", msg);
            return ExitCode::SUCCESS;
        }
        Err(cli::CliError::Version(msg)) => {
            println!("{}", msg);
            return ExitCode::SUCCESS;
        }
        Err(cli::CliError::Msg(msg, code)) => {
            eprintln!("{}", msg);
            return ExitCode::from(code);
        }
    };

    if let Some(shell) = config.generate_completions {
        print_completions(&shell);
        return ExitCode::SUCCESS;
    }

    let stdin_tty = io::stdin().is_terminal();
    let stdout_tty = io::stdout().is_terminal();
    let stderr_tty = io::stderr().is_terminal();

    let use_color = !config.no_color;

    if config.repl {
        if !stdin_tty || !stdout_tty {
            eprintln!("Error: repl argument supplied with piped input or output");
            return ExitCode::from(65);
        }
        return repl::run(use_color);
    }

    // Read input
    let input = match &config.input_file {
        Some(path) if path == "-" => {
            let mut s = String::new();
            if let Err(e) = io::stdin().read_to_string(&mut s) {
                eprintln!("Error: {}", e);
                return ExitCode::from(66);
            }
            s
        }
        Some(path) => {
            match std::fs::read_to_string(path) {
                Ok(s) => s,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    return ExitCode::from(66);
                }
            }
        }
        None => {
            if !stdin_tty {
                // Read from piped stdin
                let mut s = String::new();
                if let Err(e) = io::stdin().read_to_string(&mut s) {
                    eprintln!("Error: {}", e);
                    return ExitCode::from(66);
                }
                s
            } else {
                // No input file and stdin is a tty - print warning and help
                let msg = "No input file supplied and no input piped\nTry adding a path argument: 'melody ./file.mdy'";
                if use_color && stderr_tty {
                    eprintln!("\x1b[94m{}\x1b[0m", msg);
                } else {
                    eprintln!("{}", msg);
                }
                eprintln!();
                eprint!("{}", cli::help_text(&bin_name_only));
                return ExitCode::SUCCESS;
            }
        }
    };

    // Compile
    let result = compiler::compile(&input);
    match result {
        Ok(regex) => {
            // Possibly test
            if let Some(test_str) = &config.test {
                print_test_result(&regex, test_str, use_color, stdout_tty);
            } else if let Some(test_file) = &config.test_file {
                match std::fs::read_to_string(test_file) {
                    Ok(content) => {
                        print_test_result_file(&regex, test_file, &content, use_color, stdout_tty);
                    }
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        return ExitCode::from(66);
                    }
                }
            } else if let Some(out_path) = &config.output_file {
                if let Err(e) = std::fs::write(out_path, &regex) {
                    eprintln!("Error: {}", e);
                    return ExitCode::from(66);
                }
            } else {
                if use_color && stdout_tty {
                    println!("\x1b[94m{}\x1b[0m", regex);
                } else {
                    print!("{}", regex);
                    if stdout_tty {
                        println!();
                    } else {
                        // For piped output, do we add newline? Actually yes we should match original
                    }
                }
            }
            ExitCode::SUCCESS
        }
        Err(err) => {
            if use_color && stderr_tty {
                eprintln!("\x1b[91mError: {}\x1b[0m", err);
            } else {
                eprintln!("Error: {}", err);
            }
            ExitCode::from(65)
        }
    }
}

fn print_test_result(regex: &str, input: &str, use_color: bool, tty: bool) {
    let matched = match regex_test::test_regex(regex, input) {
        Ok(m) => m,
        Err(e) => {
            let msg = format!("Error compiling regex: {}", e);
            if use_color && tty {
                eprintln!("\x1b[91m{}\x1b[0m", msg);
            } else {
                eprintln!("{}", msg);
            }
            return;
        }
    };
    let display_input = if input.chars().count() > 10 {
        let s: String = input.chars().take(10).collect();
        format!("{}...", s)
    } else {
        input.to_string()
    };
    let status = if matched { "matched" } else { "did not match" };
    if use_color && tty {
        let color = if matched { "\x1b[92m" } else { "\x1b[91m" };
        println!("'{}' {}{}\x1b[0m", display_input, color, status);
    } else {
        println!("'{}' {}", display_input, status);
    }
}

fn print_test_result_file(regex: &str, path: &str, content: &str, use_color: bool, tty: bool) {
    let matched = match regex_test::test_regex(regex, content) {
        Ok(m) => m,
        Err(e) => {
            let msg = format!("Error compiling regex: {}", e);
            if use_color && tty {
                eprintln!("\x1b[91m{}\x1b[0m", msg);
            } else {
                eprintln!("{}", msg);
            }
            return;
        }
    };
    let status = if matched { "matched" } else { "did not match" };
    if use_color && tty {
        let color = if matched { "\x1b[92m" } else { "\x1b[91m" };
        println!("{} {}{}\x1b[0m", path, color, status);
    } else {
        println!("{} {}", path, status);
    }
}

mod regex_test {
    use std::process::{Command, Stdio};
    use std::io::Write;
    pub fn test_regex(regex: &str, input: &str) -> Result<bool, String> {
        // Use Node.js if available; else Python
        // We don't have access to external compilers; use a built-in simplistic approach.
        // Since this is a regex test, use Python's re module via subprocess.
        let py_script = format!("import sys,re\ndata=sys.stdin.read()\nm=re.search(r'''{}''', data)\nsys.exit(0 if m else 1)\n", regex.replace("'''", "\\'\\'\\'"));
        let _ = py_script;
        // Simpler: pipe to python3
        let mut cmd = Command::new("python3")
            .arg("-c")
            .arg(format!(r#"
import sys, re
regex = sys.argv[1]
data = sys.stdin.read()
try:
    m = re.search(regex, data)
    sys.exit(0 if m else 1)
except re.error as e:
    sys.stderr.write(str(e))
    sys.exit(2)
"#))
            .arg(regex)
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(|e| e.to_string())?;
        cmd.stdin.as_mut().unwrap().write_all(input.as_bytes()).map_err(|e| e.to_string())?;
        let status = cmd.wait().map_err(|e| e.to_string())?;
        match status.code() {
            Some(0) => Ok(true),
            Some(1) => Ok(false),
            _ => Err("regex error".to_string()),
        }
    }
}

fn print_completions(shell: &str) {
    match shell {
        "bash" => print!("{}", completions::BASH),
        "zsh" => print!("{}", completions::ZSH),
        "fish" => print!("{}", completions::FISH),
        "powershell" => print!("{}", completions::POWERSHELL),
        "elvish" => print!("{}", completions::ELVISH),
        _ => {
            eprintln!("error: invalid value '{}' for '--generate-completions <completions>'", shell);
        }
    }
}

mod completions {
    pub const BASH: &str = include_str!("completions/bash.sh");
    pub const ZSH: &str = include_str!("completions/zsh.sh");
    pub const FISH: &str = include_str!("completions/fish.sh");
    pub const POWERSHELL: &str = include_str!("completions/powershell.sh");
    pub const ELVISH: &str = include_str!("completions/elvish.sh");
}
