//! Character-level utilities for the hand-rolled parser

pub fn line_col(src: &str, pos: usize) -> (usize, usize, String) {
    // Returns (line number 1-indexed, column 1-indexed, line text without newline)
    let pos = pos.min(src.len());
    let mut line_start = 0usize;
    let mut line_no = 1usize;
    let bytes = src.as_bytes();
    for i in 0..pos {
        if bytes[i] == b'\n' {
            line_no += 1;
            line_start = i + 1;
        }
    }
    // Extract line content from line_start to next newline (or end)
    let line_end = src[line_start..].find('\n').map(|n| line_start + n).unwrap_or(src.len());
    let line_text = &src[line_start..line_end];
    // Column is position in characters (Pest uses 1-based, byte offsets? or char offsets?)
    // We'll use byte offset for simplicity; Pest actually uses line-col by chars.
    // For ASCII input, these are the same.
    let col_bytes = pos - line_start;
    // Count characters in the line prefix
    let col = src[line_start..line_start + col_bytes].chars().count() + 1;
    (line_no, col, line_text.to_string())
}
