//! Error types and Pest-style error formatting

use crate::lexer::line_col;

pub struct ParseError {
    pub pos: usize,
    pub expected: Vec<&'static str>,
}

impl ParseError {
    pub fn at(pos: usize, expected: &'static str) -> Self {
        Self { pos, expected: vec![expected] }
    }
    pub fn many(pos: usize, expected: Vec<&'static str>) -> Self {
        Self { pos, expected }
    }

    /// Format error Pest-style.
    pub fn format(&self, src: &str) -> String {
        let (line_no, col, line_text) = line_col(src, self.pos);
        let line_no_str = line_no.to_string();
        let line_no_width = line_no_str.len();
        let pad = " ".repeat(line_no_width);
        let caret_pad = " ".repeat(col.saturating_sub(1));

        let expected_str = format_expected_list(&self.expected);
        format!(
            " --> {}:{}\n{} |\n{} | {}\n{} | {}^---\n{} |\n{} = expected {}",
            line_no, col,
            pad,
            line_no_str, line_text,
            pad, caret_pad,
            pad,
            pad, expected_str
        )
    }
}

fn format_expected_list(items: &[&str]) -> String {
    match items.len() {
        0 => String::new(),
        1 => items[0].to_string(),
        2 => format!("{} or {}", items[0], items[1]),
        _ => {
            let mut s = String::new();
            for (i, item) in items.iter().enumerate() {
                if i == items.len() - 1 {
                    s.push_str(", or ");
                    s.push_str(item);
                } else if i > 0 {
                    s.push_str(", ");
                    s.push_str(item);
                } else {
                    s.push_str(item);
                }
            }
            s
        }
    }
}

pub enum MelodyError {
    Parse(ParseError),
    Semantic(String),
}

impl MelodyError {
    pub fn format(&self, src: &str) -> String {
        match self {
            MelodyError::Parse(e) => e.format(src),
            MelodyError::Semantic(msg) => msg.clone(),
        }
    }
}
