//! Recursive descent parser for Melody language, emitting Pest-style errors.

use crate::ast::*;
use crate::error::ParseError;

pub struct Parser<'a> {
    src: &'a str,
    pos: usize,
    /// furthest position observed for error reporting
    pub furthest: ParseError,
}

fn merge_expected(a: ParseError, b: ParseError) -> ParseError {
    if b.pos > a.pos {
        b
    } else if a.pos > b.pos {
        a
    } else {
        let mut exp = a.expected;
        for e in b.expected {
            if !exp.contains(&e) {
                exp.push(e);
            }
        }
        ParseError { pos: a.pos, expected: exp }
    }
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a str) -> Self {
        Self { src, pos: 0, furthest: ParseError { pos: 0, expected: vec![] } }
    }

    fn remember(&mut self, e: ParseError) {
        self.furthest = merge_expected(std::mem::replace(&mut self.furthest, ParseError { pos: 0, expected: vec![] }), e);
    }

    fn save(&self) -> (usize, ParseError) {
        (self.pos, ParseError { pos: self.furthest.pos, expected: self.furthest.expected.clone() })
    }
    fn restore(&mut self, s: (usize, ParseError)) {
        self.pos = s.0;
        self.furthest = s.1;
    }

    fn peek(&self) -> Option<char> {
        self.src[self.pos..].chars().next()
    }
    fn peek_byte(&self) -> Option<u8> {
        self.src.as_bytes().get(self.pos).copied()
    }
    fn advance_char(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }
    fn starts_with(&self, s: &str) -> bool {
        self.src[self.pos..].starts_with(s)
    }
    fn at_end(&self) -> bool {
        self.pos >= self.src.len()
    }
    /// Try to consume a literal string. Returns true on success.
    fn consume(&mut self, s: &str) -> bool {
        if self.starts_with(s) {
            self.pos += s.len();
            true
        } else {
            false
        }
    }
    /// Skip implicit whitespace and block comments.
    fn skip_ws_block(&mut self) {
        loop {
            // skip whitespace
            let start = self.pos;
            while let Some(c) = self.peek() {
                if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                    self.pos += c.len_utf8();
                } else {
                    break;
                }
            }
            // skip block comment
            if self.starts_with("/*") {
                self.pos += 2;
                while !self.at_end() && !self.starts_with("*/") {
                    if let Some(c) = self.peek() {
                        self.pos += c.len_utf8();
                    } else {
                        break;
                    }
                }
                if self.starts_with("*/") {
                    self.pos += 2;
                }
                continue;
            }
            if self.pos == start {
                break;
            }
        }
    }

    /// Skip whitespace (including newlines) but not comments.
    /// Used when line comments might follow.
    fn skip_ws_and_line_comment(&mut self) {
        loop {
            self.skip_ws_block();
            // Try line comment; only allowed at "line start" — we implement by
            // allowing it anywhere the WS has landed to simplify. We'll filter below.
            if self.starts_with("//") {
                // consume until newline
                while let Some(c) = self.peek() {
                    if c == '\n' {
                        break;
                    }
                    self.pos += c.len_utf8();
                }
                // continue looping to consume following ws/comments
                continue;
            }
            break;
        }
    }

    pub fn parse_root(&mut self) -> Result<Vec<Node>, ParseError> {
        let mut nodes = Vec::new();
        self.skip_ws_and_line_comment();
        while !self.at_end() {
            let stmt = self.parse_stmt(true)?;
            if let Some(n) = stmt {
                nodes.push(n);
            }
            self.skip_ws_and_line_comment();
        }
        Ok(nodes)
    }

    /// Parses either an expression with trailing ';' (simple statement)
    /// or a block-based statement (group decl, assertion, let decl).
    /// Returns Ok(None) if the statement was a line comment (already consumed).
    fn parse_stmt(&mut self, top_level: bool) -> Result<Option<Node>, ParseError> {
        // Already ws-stripped.
        let node = self.parse_statement_inner(top_level)?;
        Ok(Some(node))
    }

    fn parse_statement_inner(&mut self, _top_level: bool) -> Result<Node, ParseError> {
        let start_pos = self.pos;
        // Try let declaration first
        if self.try_keyword("let") {
            return self.parse_let_body();
        }

        // Try to parse an expression, then require ';'
        // Or it could be a group/assertion declaration without ';'.
        let expr = self.parse_expression(start_pos)?;

        // If it's a group/assertion/variable declaration (block-based), no ';' needed.
        let needs_semi = match &expr {
            Node::Group(_, _) | Node::Assertion(_, _) => false,
            Node::Quantifier(_, inner) => {
                // If the inner is a group/assertion, still no ';' ... actually yes ';' needed
                // Let's test: "some of match { }" - succeeds. Does it need ';'?
                // From earlier test: "some of match { \"a\"; \"b\"; }" succeeds (without trailing ';')
                // But "some of match { \"a\"; \"b\"; };" fails.
                // So quantifier+group also doesn't need ';' trailing.
                !matches!(**inner, Node::Group(_, _) | Node::Assertion(_, _))
            }
            _ => true,
        };

        if needs_semi {
            self.skip_ws_block();
            if !self.consume(";") {
                // Not a ';' — error
                // For groups-as-expressions, we might have group_declaration or assertion_declaration etc
                let expected = match &expr {
                    _ => vec!["quantifier_quantity", "group_declaration", "assertion_declaration", "variable_declaration"],
                };
                return Err(self.make_error(expected));
            }
        }
        Ok(expr)
    }

    fn parse_let_body(&mut self) -> Result<Node, ParseError> {
        self.skip_ws_block();
        // variable_name: "." identifier
        if !self.consume(".") {
            return Err(self.make_error(vec!["variable_name"]));
        }
        let name = self.parse_identifier()?;
        self.skip_ws_block();
        if !self.consume("=") {
            return Err(self.make_error(vec!["="]));
        }
        self.skip_ws_block();
        // Must be a block { ... }
        let block = self.parse_block()?;
        Ok(Node::VarDecl(name, block))
    }

    fn parse_identifier(&mut self) -> Result<String, ParseError> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() || c == '_' {
                self.pos += c.len_utf8();
            } else {
                break;
            }
        }
        if self.pos == start {
            return Err(self.make_error(vec!["identifier"]));
        }
        Ok(self.src[start..self.pos].to_string())
    }

    /// Parse '{' ... '}' - a block of inner statements
    fn parse_block(&mut self) -> Result<Vec<Node>, ParseError> {
        if !self.consume("{") {
            return Err(self.make_error(vec!["block"]));
        }
        let mut nodes = Vec::new();
        self.skip_ws_and_line_comment();
        while !self.at_end() && !self.starts_with("}") {
            let stmt = self.parse_stmt(false)?;
            if let Some(n) = stmt {
                nodes.push(n);
            }
            self.skip_ws_and_line_comment();
        }
        if !self.consume("}") {
            return Err(self.make_error(vec!["literal", "raw", "not", "range", "quantifier_quantity", "group_declaration", "assertion_declaration", "variable_declaration", "variable_invocation"]));
        }
        Ok(nodes)
    }

    /// Parse an expression (not including trailing ';').
    /// `_start_pos` is used for error context.
    fn parse_expression(&mut self, _start_pos: usize) -> Result<Node, ParseError> {
        // Try "not" prefix
        if self.try_keyword("not") {
            // not + (symbol/range/assertion)
            self.skip_ws_block();
            // Check if it's an assertion ("ahead" or "behind")
            let before = self.pos;
            if self.try_keyword("ahead") {
                self.skip_ws_block();
                let block = self.parse_block()?;
                return Ok(Node::Assertion(AssertionKind::NotAhead, block));
            }
            self.pos = before;
            if self.try_keyword("behind") {
                self.skip_ws_block();
                let block = self.parse_block()?;
                return Ok(Node::Assertion(AssertionKind::NotBehind, block));
            }
            self.pos = before;
            // Otherwise it's `not <symbol>` or `not a to z` or `not <category::X>`
            // or `not <any class_content>`
            let content = self.parse_class_content_or_symbol()?;
            // Apply negation: we return a wrapped marker that the compiler handles
            return Ok(self.apply_negation(content)?);
        }

        // Try quantifier
        if let Some(q) = self.try_quantifier()? {
            // "some of X", "any of X", etc.
            self.skip_ws_block();
            // Parse the target of the quantifier (basic_expr)
            let inner = self.parse_quantifier_target()?;
            return Ok(Node::Quantifier(q, Box::new(inner)));
        }

        // Otherwise try basic expression
        self.parse_basic_expr()
    }

    fn parse_quantifier_target(&mut self) -> Result<Node, ParseError> {
        // After a quantifier, may be: literal/raw/not/range/group/assertion/varinvocation
        // Not another quantifier.
        if self.try_keyword("not") {
            self.skip_ws_block();
            // assertion or class content
            let before = self.pos;
            if self.try_keyword("ahead") {
                self.skip_ws_block();
                let block = self.parse_block()?;
                return Ok(Node::Assertion(AssertionKind::NotAhead, block));
            }
            self.pos = before;
            if self.try_keyword("behind") {
                self.skip_ws_block();
                let block = self.parse_block()?;
                return Ok(Node::Assertion(AssertionKind::NotBehind, block));
            }
            self.pos = before;
            let content = self.parse_class_content_or_symbol()?;
            return Ok(self.apply_negation(content)?);
        }
        self.parse_basic_expr()
    }

    /// Parse `not <X>` content: symbol, range, category
    fn parse_class_content_or_symbol(&mut self) -> Result<Node, ParseError> {
        // class_content: symbol or range
        // assertion_type: "ahead" | "behind" (handled above)
        if let Some(n) = self.try_range()? {
            return Ok(n);
        }
        if let Some(n) = self.try_symbol()? {
            return Ok(n);
        }
        Err(self.make_error(vec!["class_content"]))
    }

    /// Apply negation to a node. Returns node or error.
    fn apply_negation(&mut self, node: Node) -> Result<Node, ParseError> {
        match node {
            Node::Symbol(s) => {
                match s {
                    Symbol::Char => Err(self.make_semantic("negative char not allowed")),
                    Symbol::Start => Err(self.make_semantic("negative start not allowed")),
                    Symbol::End => Err(self.make_semantic("negative end not allowed")),
                    _ => Ok(Node::Raw(compile_symbol(&s, true))),
                }
            }
            Node::Range(from, to, _) => Ok(Node::Range(from, to, true)),
            Node::Category(code, _) => Ok(Node::Category(code, true)),
            _ => Ok(node),
        }
    }

    fn make_semantic(&self, msg: &str) -> ParseError {
        // Hack: we use ParseError to carry the message; the caller should detect this.
        // Actually, let's represent semantic errors differently.
        // For simplicity, encode semantic error by using a special expected list.
        ParseError { pos: usize::MAX, expected: vec![Box::leak(format!("__SEMANTIC__{}", msg).into_boxed_str())] }
    }

    /// Try to parse a quantifier prefix ("some of", "N of", etc.)
    /// Returns Ok(Some(q)) if consumed, Ok(None) if no quantifier here.
    fn try_quantifier(&mut self) -> Result<Option<Quantifier>, ParseError> {
        let save = self.save();
        // Check for "some", "any", "option", integer, or "over"
        if self.try_keyword_bounded("some") {
            self.skip_ws_block();
            if self.try_keyword_bounded("of") {
                return Ok(Some(Quantifier::Some));
            }
            self.restore(save);
            return Ok(None);
        }
        if self.try_keyword_bounded("any") {
            self.skip_ws_block();
            if self.try_keyword_bounded("of") {
                return Ok(Some(Quantifier::Any));
            }
            self.restore(save);
            return Ok(None);
        }
        if self.try_keyword_bounded("option") {
            self.skip_ws_block();
            if self.try_keyword_bounded("of") {
                return Ok(Some(Quantifier::Option));
            }
            self.restore(save);
            return Ok(None);
        }
        if self.try_keyword_bounded("over") {
            self.skip_ws_block();
            let n = self.parse_integer()?;
            self.skip_ws_block();
            if self.try_keyword_bounded("of") {
                return Ok(Some(Quantifier::Over(n)));
            }
            // partial match but missing "of"
            return Err(self.make_error(vec!["of"]));
        }
        // integer — may be "N of" or "N to M of"
        if let Some(n) = self.try_integer() {
            self.skip_ws_block();
            if self.try_keyword_bounded("to") {
                self.skip_ws_block();
                let m = match self.try_integer() {
                    Some(x) => x,
                    None => return Err(self.make_error(vec!["amount"])),
                };
                self.skip_ws_block();
                if self.try_keyword_bounded("of") {
                    if m < n {
                        return Err(self.make_semantic("usage of an invalid quantifier range"));
                    }
                    return Ok(Some(Quantifier::Range(n, m)));
                }
                return Err(self.make_error(vec!["of"]));
            }
            if self.try_keyword_bounded("of") {
                return Ok(Some(Quantifier::Exact(n)));
            }
            // Integer not followed by "of" or "to" — could be a range "N to M" where M is another integer
            self.restore(save);
            return Ok(None);
        }
        Ok(None)
    }

    fn try_integer(&mut self) -> Option<u64> {
        let start = self.pos;
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        if s.is_empty() {
            self.pos = start;
            return None;
        }
        s.parse().ok()
    }

    fn parse_integer(&mut self) -> Result<u64, ParseError> {
        match self.try_integer() {
            Some(n) => Ok(n),
            None => Err(self.make_error(vec!["integer"])),
        }
    }

    fn parse_basic_expr(&mut self) -> Result<Node, ParseError> {
        // Literal, raw, range, symbol, group, assertion, var_invocation
        if let Some(n) = self.try_literal()? {
            return Ok(n);
        }
        if let Some(n) = self.try_raw()? {
            return Ok(n);
        }
        if let Some(n) = self.try_range()? {
            return Ok(n);
        }
        if let Some(n) = self.try_symbol()? {
            return Ok(n);
        }
        if let Some(n) = self.try_group()? {
            return Ok(n);
        }
        if let Some(n) = self.try_assertion()? {
            return Ok(n);
        }
        if let Some(n) = self.try_var_invocation()? {
            return Ok(n);
        }
        Err(self.make_error(vec!["literal", "raw", "not", "range", "group_declaration", "assertion_declaration", "variable_declaration", "variable_invocation"]))
    }

    fn try_literal(&mut self) -> Result<Option<Node>, ParseError> {
        let ch = match self.peek() {
            Some('"') => '"',
            Some('\'') => '\'',
            _ => return Ok(None),
        };
        let start = self.pos;
        self.pos += 1;
        let mut content = String::new();
        let mut closed = false;
        while let Some(c) = self.peek() {
            if c == ch {
                self.pos += 1;
                closed = true;
                break;
            }
            if c == '\\' {
                // Escape: allow \", \', \\, \n, \t, \r, \f, \b
                self.pos += 1;
                let next = self.peek();
                match next {
                    Some(nc @ ('"' | '\'' | '\\' | 'n' | 't' | 'r' | 'f' | 'b')) => {
                        // Keep original representation: \n preserved as \n
                        if nc == ch {
                            content.push(nc);
                        } else if nc == '\\' {
                            content.push('\\');
                            content.push('\\');
                        } else {
                            content.push('\\');
                            content.push(nc);
                        }
                        self.pos += 1;
                    }
                    _ => {
                        // Invalid escape
                        self.pos = start;
                        return Ok(None);
                    }
                }
                continue;
            }
            content.push(c);
            self.pos += c.len_utf8();
        }
        if !closed {
            self.pos = start;
            return Ok(None);
        }
        if content.is_empty() {
            // Empty literal - treat as invalid
            self.pos = start;
            return Ok(None);
        }
        Ok(Some(Node::Literal(content)))
    }

    fn try_raw(&mut self) -> Result<Option<Node>, ParseError> {
        if self.peek() != Some('`') {
            return Ok(None);
        }
        let start = self.pos;
        self.pos += 1;
        let mut content = String::new();
        let mut closed = false;
        while let Some(c) = self.peek() {
            if c == '`' {
                self.pos += 1;
                closed = true;
                break;
            }
            if c == '\\' {
                self.pos += 1;
                let next = self.peek();
                match next {
                    Some('`') => { content.push('`'); self.pos += 1; }
                    Some('\\') => { content.push('\\'); content.push('\\'); self.pos += 1; }
                    _ => { self.pos = start; return Ok(None); }
                }
                continue;
            }
            content.push(c);
            self.pos += c.len_utf8();
        }
        if !closed || content.is_empty() {
            self.pos = start;
            return Ok(None);
        }
        Ok(Some(Node::Raw(content)))
    }

    fn try_range(&mut self) -> Result<Option<Node>, ParseError> {
        // `a to z` or `0 to 9` — two chars separated by " to "
        // Must be: alpha-char or digit-char, optional ws, "to", ws, alpha-char or digit-char
        let save = self.save();
        let c1 = match self.peek() {
            Some(c) if c.is_ascii_alphabetic() || c.is_ascii_digit() => c,
            _ => return Ok(None),
        };
        // Make sure it's a single-char identifier (not part of a keyword/identifier)
        // Check c2 after c1 is not alpha
        let after = self.src[self.pos + c1.len_utf8()..].chars().next();
        if let Some(ac) = after {
            if ac.is_ascii_alphanumeric() || ac == '_' {
                return Ok(None);
            }
        }
        self.pos += c1.len_utf8();
        self.skip_ws_block();
        if !self.try_keyword_bounded("to") {
            self.restore(save);
            return Ok(None);
        }
        self.skip_ws_block();
        let c2 = match self.peek() {
            Some(c) if c.is_ascii_alphabetic() || c.is_ascii_digit() => c,
            _ => {
                self.restore(save);
                return Ok(None);
            }
        };
        let after2 = self.src[self.pos + c2.len_utf8()..].chars().next();
        if let Some(ac) = after2 {
            if ac.is_ascii_alphanumeric() || ac == '_' {
                self.restore(save);
                return Ok(None);
            }
        }
        self.pos += c2.len_utf8();
        Ok(Some(Node::Range(c1, c2, false)))
    }

    fn try_symbol(&mut self) -> Result<Option<Node>, ParseError> {
        if self.peek() != Some('<') {
            return Ok(None);
        }
        let start = self.pos;
        self.pos += 1;
        // symbol_identifier
        let ident_start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() || c == '_' {
                self.pos += c.len_utf8();
            } else {
                break;
            }
        }
        if self.pos == ident_start {
            // After '<', expected symbol_identifier
            return Err(self.make_error(vec!["symbol_identifier"]));
        }
        let name = self.src[ident_start..self.pos].to_string();
        // Possibly `::subname`
        let subname = if self.starts_with("::") {
            self.pos += 2;
            let sub_start = self.pos;
            while let Some(c) = self.peek() {
                if c.is_ascii_alphabetic() || c == '_' {
                    self.pos += c.len_utf8();
                } else {
                    break;
                }
            }
            if self.pos == sub_start {
                return Err(self.make_error(vec!["symbol_identifier"]));
            }
            Some(self.src[sub_start..self.pos].to_string())
        } else {
            None
        };
        if !self.consume(">") {
            self.pos = start;
            return Ok(None);
        }

        if let Some(sub) = subname {
            // Expecting `category`
            if name != "category" {
                return Err(self.make_semantic("usage of an unrecognized symbol namespace"));
            }
            let code = match crate::compiler::category_to_code(&sub) {
                Some(c) => c,
                None => return Err(self.make_semantic("usage of an unrecognized unicode category")),
            };
            return Ok(Some(Node::Category(code.to_string(), false)));
        }

        if let Some(s) = Symbol::from_name(&name) {
            return Ok(Some(Node::Symbol(s)));
        }
        Err(self.make_semantic("usage of an unrecognized symbol"))
    }

    fn try_group(&mut self) -> Result<Option<Node>, ParseError> {
        let save = self.save();
        if self.try_keyword("match") {
            self.skip_ws_block();
            let block = self.parse_block()?;
            return Ok(Some(Node::Group(GroupKind::Match, block)));
        }
        if self.try_keyword("either") {
            self.skip_ws_block();
            let block = self.parse_block()?;
            return Ok(Some(Node::Group(GroupKind::Either, block)));
        }
        if self.try_keyword("capture") {
            // Optional identifier(s) before block
            self.skip_ws_block();
            // Check if next is '{' or an identifier
            if self.peek() == Some('{') {
                let block = self.parse_block()?;
                return Ok(Some(Node::Group(GroupKind::Capture(None), block)));
            }
            // Parse identifier(s) space-separated
            let mut name_parts = Vec::new();
            let mut name_src_start = self.pos;
            if let Some(c) = self.peek() {
                if !(c.is_ascii_alphabetic() || c == '_') {
                    return Err(self.make_error(vec!["block", "identifier"]));
                }
            } else {
                return Err(self.make_error(vec!["block", "identifier"]));
            }
            loop {
                let id_start = self.pos;
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphabetic() || c == '_' {
                        self.pos += c.len_utf8();
                    } else {
                        break;
                    }
                }
                if self.pos == id_start {
                    break;
                }
                name_parts.push((id_start, self.pos));
                // Peek ahead past whitespace for another identifier
                let s = self.save();
                self.skip_ws_block();
                match self.peek() {
                    Some(c) if c.is_ascii_alphabetic() || c == '_' => continue,
                    Some('{') => break,
                    _ => {
                        self.restore(s);
                        break;
                    }
                }
            }
            if name_parts.is_empty() {
                self.restore(save);
                return Ok(None);
            }
            let first = name_parts[0].0;
            let last = name_parts.last().unwrap().1;
            let name_text = self.src[first..last].to_string();
            let _ = name_src_start;
            self.skip_ws_block();
            let block = self.parse_block()?;
            return Ok(Some(Node::Group(GroupKind::Capture(Some(name_text)), block)));
        }
        Ok(None)
    }

    fn try_assertion(&mut self) -> Result<Option<Node>, ParseError> {
        if self.try_keyword("ahead") {
            self.skip_ws_block();
            let block = self.parse_block()?;
            return Ok(Some(Node::Assertion(AssertionKind::Ahead, block)));
        }
        if self.try_keyword("behind") {
            self.skip_ws_block();
            let block = self.parse_block()?;
            return Ok(Some(Node::Assertion(AssertionKind::Behind, block)));
        }
        Ok(None)
    }

    fn try_var_invocation(&mut self) -> Result<Option<Node>, ParseError> {
        if self.peek() != Some('.') {
            return Ok(None);
        }
        let start = self.pos;
        self.pos += 1;
        let name = match self.try_identifier_opt() {
            Some(n) => n,
            None => {
                self.pos = start;
                return Ok(None);
            }
        };
        Ok(Some(Node::VarInvocation(name)))
    }

    fn try_identifier_opt(&mut self) -> Option<String> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() || c == '_' {
                self.pos += c.len_utf8();
            } else {
                break;
            }
        }
        if self.pos == start {
            return None;
        }
        Some(self.src[start..self.pos].to_string())
    }

    fn try_keyword(&mut self, kw: &str) -> bool {
        if self.starts_with(kw) {
            let after = self.pos + kw.len();
            if let Some(c) = self.src[after..].chars().next() {
                if c.is_ascii_alphanumeric() || c == '_' {
                    return false;
                }
            }
            self.pos += kw.len();
            return true;
        }
        false
    }
    fn try_keyword_bounded(&mut self, kw: &str) -> bool {
        self.try_keyword(kw)
    }

    fn make_error(&mut self, expected: Vec<&'static str>) -> ParseError {
        let e = ParseError::many(self.pos, expected);
        self.remember(ParseError { pos: e.pos, expected: e.expected.clone() });
        ParseError { pos: self.furthest.pos, expected: self.furthest.expected.clone() }
    }
}

fn compile_symbol(s: &Symbol, negated: bool) -> String {
    match (s, negated) {
        (Symbol::Char, false) => ".".into(),
        (Symbol::Space, false) => " ".into(),
        (Symbol::Space, true) => "[^ ]".into(),
        (Symbol::Whitespace, false) => "\\s".into(),
        (Symbol::Whitespace, true) => "\\S".into(),
        (Symbol::Digit, false) => "\\d".into(),
        (Symbol::Digit, true) => "\\D".into(),
        (Symbol::Word, false) => "\\w".into(),
        (Symbol::Word, true) => "\\W".into(),
        (Symbol::Newline, false) => "\\n".into(),
        (Symbol::Newline, true) => "[^\\n]".into(),
        (Symbol::Tab, false) => "\\t".into(),
        (Symbol::Tab, true) => "[^\\t]".into(),
        (Symbol::Backspace, false) => "[\\b]".into(),
        (Symbol::Backspace, true) => "[^\\b]".into(),
        (Symbol::Return, false) => "\\r".into(),
        (Symbol::Return, true) => "[^\\r]".into(),
        (Symbol::Feed, false) => "\\f".into(),
        (Symbol::Feed, true) => "[^\\f]".into(),
        (Symbol::Null, false) => "\\0".into(),
        (Symbol::Null, true) => "[^\\0]".into(),
        (Symbol::Vertical, false) => "\\v".into(),
        (Symbol::Vertical, true) => "[^\\v]".into(),
        (Symbol::Alphabetic, false) => "[a-zA-Z]".into(),
        (Symbol::Alphabetic, true) => "[^a-zA-Z]".into(),
        (Symbol::Alphanumeric, false) => "[a-zA-Z0-9]".into(),
        (Symbol::Alphanumeric, true) => "[^a-zA-Z0-9]".into(),
        (Symbol::Boundary, false) => "\\b".into(),
        (Symbol::Boundary, true) => "\\B".into(),
        (Symbol::Start, false) => "^".into(),
        (Symbol::Start, true) => "^".into(),
        (Symbol::End, false) => "$".into(),
        (Symbol::End, true) => "$".into(),
    }
}
