                if use_color && stderr_tty {
                    eprintln!("\x1b[94m{}\x1b[0m", msg);
                } else {
                    eprintln!("{}", msg);
                }
                eprintln!();
                eprint!("{}", cli::help_text(&bin_name));
                return ExitCode::SUCCESS;
            }
        }
    };

    // Compile
    match compiler::compile(&input) {
        Ok(regex) => {
