//! Pest-style error formatter

pub struct Error {
    pub kind: ErrKind,
}

pub enum ErrKind {
    Parse { pos: usize, expected: Vec<String> },
    Semantic(String),
}

impl Error {
    pub fn parse(pos: usize, expected: Vec<&'static str>) -> Self {
        Self { kind: ErrKind::Parse { pos, expected: expected.into_iter().map(String::from).collect() } }
    }
    pub fn semantic(msg: impl Into<String>) -> Self {
        Self { kind: ErrKind::Semantic(msg.into()) }
    }
    pub fn format(&self, src: &str) -> String {
        match &self.kind {
            ErrKind::Semantic(s) => s.clone(),
            ErrKind::Parse { pos, expected } => format_parse(*pos, expected, src),
        }
    }
}

fn format_parse(pos: usize, expected: &[String], src: &str) -> String {
    let (line, col, text) = line_col(src, pos);
    let width = line.to_string().len();
    let pad = " ".repeat(width);
    let caret_pad = " ".repeat(col.saturating_sub(1));
    let exp = format_list(expected);
    format!(
        " --> {}:{}\n{} |\n{} | {}\n{} | {}^---\n{} |\n{} = expected {}",
        line, col,
        pad,
        line, text,
        pad, caret_pad,
        pad,
        pad, exp
    )
}

pub fn line_col(src: &str, pos: usize) -> (usize, usize, String) {
    let pos = pos.min(src.len());
    let mut line_start = 0usize;
    let mut line_no = 1usize;
    let bytes = src.as_bytes();
    for i in 0..pos {
        if bytes[i] == b'\n' {
            line_no += 1;
            line_start = i + 1;
        }
    }
    let line_end = src[line_start..].find('\n').map(|n| line_start + n).unwrap_or(src.len());
    let line_text = src[line_start..line_end].to_string();
    let prefix = &src[line_start..pos];
    let col = prefix.chars().count() + 1;
    (line_no, col, line_text)
}

fn format_list(items: &[String]) -> String {
    match items.len() {
        0 => String::new(),
        1 => items[0].clone(),
        2 => format!("{} or {}", items[0], items[1]),
        _ => {
            let mut s = String::new();
            for (i, it) in items.iter().enumerate() {
                if i == items.len() - 1 {
                    s.push_str(", or ");
                    s.push_str(it);
                } else if i > 0 {
                    s.push_str(", ");
                    s.push_str(it);
                } else {
                    s.push_str(it);
                }
            }
            s
        }
    }
}
