//! Recursive-descent Melody parser

use crate::ast::*;
use crate::errfmt::Error;

pub struct P<'a> {
    src: &'a str,
    pub pos: usize,
    /// Farthest failure position and expected rule names there.
    farthest: usize,
    expected: Vec<&'static str>,
}

#[derive(Debug)]
pub struct Fail;

impl<'a> P<'a> {
    pub fn new(src: &'a str) -> Self { Self { src, pos: 0, farthest: 0, expected: vec![] } }

    fn record(&mut self, exp: &'static str) {
        if self.pos > self.farthest {
            self.farthest = self.pos;
            self.expected.clear();
        }
        if self.pos == self.farthest && !self.expected.contains(&exp) {
            self.expected.push(exp);
        }
    }
    fn record_many(&mut self, exps: &[&'static str]) {
        if self.pos > self.farthest {
            self.farthest = self.pos;
            self.expected.clear();
        }
        if self.pos == self.farthest {
            for e in exps {
                if !self.expected.contains(e) { self.expected.push(*e); }
            }
        }
    }

    pub fn error(&self) -> Error {
        Error::parse(self.farthest, self.expected.clone())
    }

    fn peek(&self) -> Option<char> { self.src[self.pos..].chars().next() }
    fn starts(&self, s: &str) -> bool { self.src[self.pos..].starts_with(s) }
    fn eof(&self) -> bool { self.pos >= self.src.len() }

    fn save(&self) -> usize { self.pos }
    fn restore(&mut self, p: usize) { self.pos = p; }

    /// Skip spaces/newlines/tabs and block comments. Always succeeds.
    fn skip_ws(&mut self) {
        loop {
            let before = self.pos;
            while let Some(c) = self.peek() {
                if c == ' ' || c == '\t' || c == '\n' || c == '\r' { self.pos += c.len_utf8(); }
                else { break; }
            }
            if self.starts("/*") {
                self.pos += 2;
                while !self.eof() && !self.starts("*/") {
                    if let Some(c) = self.peek() { self.pos += c.len_utf8(); }
                }
                if self.starts("*/") { self.pos += 2; }
                continue;
            }
            if self.pos == before { break; }
        }
    }

    /// Skip whitespace INCLUDING line comments (only valid where they can be statements).
    fn skip_ws_and_line(&mut self) {
        loop {
            self.skip_ws();
            if self.starts("//") {
                while let Some(c) = self.peek() {
                    if c == '\n' { break; }
                    self.pos += c.len_utf8();
                }
                continue;
            }
            break;
        }
    }

    fn consume_str(&mut self, s: &str) -> bool {
        if self.starts(s) { self.pos += s.len(); true } else { false }
    }

    fn try_keyword(&mut self, kw: &str) -> bool {
        if !self.starts(kw) { return false; }
        let after = self.pos + kw.len();
        if let Some(c) = self.src[after..].chars().next() {
            if c.is_ascii_alphanumeric() || c == '_' { return false; }
        }
        self.pos += kw.len();
        true
    }

    pub fn parse_root(&mut self) -> Result<Vec<Node>, Error> {
        self.skip_ws_and_line();
        let mut items = Vec::new();
        while !self.eof() {
            match self.parse_stmt() {
                Ok(n) => items.push(n),
                Err(Fail) => {
                    // failed at root level
                    self.record("EOI");
                    if items.is_empty() {
                        // No statements parsed — blame on "root"
                        return Err(Error::parse(0, vec!["root"]));
                    }
                    return Err(self.error());
                }
            }
            self.skip_ws_and_line();
        }
        Ok(items)
    }

    /// Parse a block: '{' (stmt | line_comment)* '}'
    pub fn parse_block(&mut self) -> Result<Vec<Node>, Fail> {
        if !self.consume_str("{") {
            self.record("block");
            return Err(Fail);
        }
        self.skip_ws_and_line();
        let mut nodes = Vec::new();
        while !self.eof() && !self.starts("}") {
            let n = self.parse_stmt_in_block()?;
            nodes.push(n);
            self.skip_ws_and_line();
        }
        if !self.consume_str("}") {
            return Err(Fail);
        }
        Ok(nodes)
    }

    /// Parse a top-level statement. Either an expr;, or a block-based declaration.
    fn parse_stmt(&mut self) -> Result<Node, Fail> {
        self.parse_statement_common(true)
    }

    /// Parse a statement inside a block. Slightly different expected lists.
    fn parse_stmt_in_block(&mut self) -> Result<Node, Fail> {
        self.parse_statement_common(false)
    }

    fn parse_statement_common(&mut self, top: bool) -> Result<Node, Fail> {
        // Try let declaration (takes no trailing ';')
        let save = self.save();
        if self.try_keyword("let") {
            self.skip_ws();
            if !self.consume_str(".") { self.restore(save); self.record("variable_name"); return Err(Fail); }
            let name = match self.parse_identifier() {
                Some(n) => n,
                None => { self.record("identifier"); return Err(Fail); }
            };
            self.skip_ws();
            if !self.consume_str("=") { self.record("="); return Err(Fail); }
            self.skip_ws();
            let block = self.parse_block()?;
            return Ok(Node::VarDecl(name, block));
        }
        // Try expression
        let save = self.save();
        let expr = match self.parse_expression() {
            Ok(e) => e,
            Err(Fail) => {
                self.restore(save);
                let expected: Vec<&'static str> = if top {
                    vec!["EOI", "literal", "raw", "not", "range", "quantifier_quantity", "group_declaration", "assertion_declaration", "variable_declaration", "variable_invocation"]
                } else {
                    vec!["literal", "raw", "not", "range", "quantifier_quantity", "group_declaration", "assertion_declaration", "variable_declaration", "variable_invocation"]
                };
                self.record_many(&expected);
                return Err(Fail);
            }
        };
        // Need trailing ';' if not a block-based expression
        let needs_semi = match &expr {
            Node::Group(_, _) | Node::Assertion(_, _) => false,
            Node::Quantifier(_, inner) => !matches!(**inner, Node::Group(_, _) | Node::Assertion(_, _)),
            _ => true,
        };
        if needs_semi {
            self.skip_ws();
            if !self.consume_str(";") {
                self.record_many(&[
                    "quantifier_quantity", "group_declaration", "assertion_declaration", "variable_declaration",
                ]);
                return Err(Fail);
            }
        }
        Ok(expr)
    }

    fn parse_identifier(&mut self) -> Option<String> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() || c == '_' { self.pos += c.len_utf8(); } else { break; }
        }
        if self.pos == start { return None; }
        Some(self.src[start..self.pos].to_string())
    }

    /// Parse an expression.
    fn parse_expression(&mut self) -> Result<Node, Fail> {
        // not-expression
        let save = self.save();
        if self.try_keyword("not") {
            self.skip_ws();
            // "not ahead { ... }" or "not behind { ... }"
            let save2 = self.save();
            if self.try_keyword("ahead") {
                self.skip_ws();
                let b = self.parse_block()?;
                return Ok(Node::Assertion(AssertionKind::NotAhead, b));
            }
            self.restore(save2);
            if self.try_keyword("behind") {
                self.skip_ws();
                let b = self.parse_block()?;
                return Ok(Node::Assertion(AssertionKind::NotBehind, b));
            }
            self.restore(save2);
            // class content: range or symbol/category
            if let Some(n) = self.try_range_or_symbol(true)? {
                return Ok(n);
            }
            // class_content failed
            self.record_many(&["amount", "class_content", "assertion_type"]);
            return Err(Fail);
        }
        self.restore(save);

        // Quantifier?
        if let Some(q) = self.try_quantifier()? {
            self.skip_ws();
            // Parse the basic expression (no quantifier recursion)
            let target = self.parse_quantifier_target()?;
            return Ok(Node::Quantifier(q, Box::new(target)));
        }

        // Basic expression
        self.parse_basic_expr()
    }

    fn parse_quantifier_target(&mut self) -> Result<Node, Fail> {
        // After quantifier prefix: can be not-expr, literal/raw/range/symbol/group/assertion/var
        // but NOT another quantifier.
        let save = self.save();
        if self.try_keyword("not") {
            self.skip_ws();
            let save2 = self.save();
            if self.try_keyword("ahead") {
                self.skip_ws();
                let b = self.parse_block()?;
                return Ok(Node::Assertion(AssertionKind::NotAhead, b));
            }
            self.restore(save2);
            if self.try_keyword("behind") {
                self.skip_ws();
                let b = self.parse_block()?;
                return Ok(Node::Assertion(AssertionKind::NotBehind, b));
            }
            self.restore(save2);
            if let Some(n) = self.try_range_or_symbol(true)? {
                return Ok(n);
            }
            self.record_many(&["amount", "class_content", "assertion_type"]);
            return Err(Fail);
        }
        self.restore(save);
        // no `raw` here? Actually the error hint lists "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"
        // We implemented raw in parse_basic_expr, so call it.
        self.parse_basic_expr_no_raw()
    }

    fn parse_basic_expr(&mut self) -> Result<Node, Fail> {
        if let Some(n) = self.try_literal()? { return Ok(n); }
        if let Some(n) = self.try_raw()? { return Ok(n); }
        if let Some(n) = self.try_range_or_symbol(false)? { return Ok(n); }
        if let Some(n) = self.try_group()? { return Ok(n); }
        if let Some(n) = self.try_assertion()? { return Ok(n); }
        if let Some(n) = self.try_var_invocation()? { return Ok(n); }
        self.record_many(&[
            "literal", "raw", "not", "range",
            "group_declaration", "assertion_declaration", "variable_declaration", "variable_invocation",
        ]);
        Err(Fail)
    }

    fn parse_basic_expr_no_raw(&mut self) -> Result<Node, Fail> {
        // same as parse_basic_expr for now; keep for future diffs
        self.parse_basic_expr()
    }

    fn try_literal(&mut self) -> Result<Option<Node>, Fail> {
        let q = match self.peek() {
            Some('"') => '"',
            Some('\'') => '\'',
            _ => return Ok(None),
        };
        let start = self.pos;
        self.pos += 1;
        let mut content = String::new();
        loop {
            match self.peek() {
                None => { self.restore(start); return Ok(None); }
                Some(c) if c == q => { self.pos += 1; break; }
                Some('\\') => {
                    let save = self.pos;
                    self.pos += 1;
                    match self.peek() {
                        Some(nc @ ('"' | '\'' | '\\' | 'n' | 't' | 'r' | 'f' | 'b')) => {
                            if nc == q {
                                content.push(nc);
                            } else if nc == '\\' {
                                content.push('\\');
                                content.push('\\');
                            } else {
                                content.push('\\');
                                content.push(nc);
                            }
                            self.pos += 1;
                        }
                        _ => { self.restore(start); return Ok(None); }
                    }
                    let _ = save;
                }
                Some(c) => { content.push(c); self.pos += c.len_utf8(); }
            }
        }
        if content.is_empty() {
            self.restore(start);
            return Ok(None);
        }
        Ok(Some(Node::Literal(content)))
    }

    fn try_raw(&mut self) -> Result<Option<Node>, Fail> {
        if self.peek() != Some('`') { return Ok(None); }
        let start = self.pos;
        self.pos += 1;
        let mut content = String::new();
        loop {
            match self.peek() {
                None => { self.restore(start); return Ok(None); }
                Some('`') => { self.pos += 1; break; }
                Some('\\') => {
                    self.pos += 1;
                    match self.peek() {
                        Some('`') => { content.push('`'); self.pos += 1; }
                        Some('\\') => { content.push('\\'); content.push('\\'); self.pos += 1; }
                        _ => { self.restore(start); return Ok(None); }
                    }
                }
                Some(c) => { content.push(c); self.pos += c.len_utf8(); }
            }
        }
        if content.is_empty() { self.restore(start); return Ok(None); }
        Ok(Some(Node::Raw(content)))
    }

    /// Try range `a to z` / `0 to 9`, or symbol `<x>`.
    /// If `for_negation` is true, parse in negation context.
    fn try_range_or_symbol(&mut self, for_negation: bool) -> Result<Option<Node>, Fail> {
        if let Some(n) = self.try_range(for_negation)? { return Ok(Some(n)); }
        if let Some(n) = self.try_symbol(for_negation)? { return Ok(Some(n)); }
        Ok(None)
    }

    fn try_range(&mut self, for_negation: bool) -> Result<Option<Node>, Fail> {
        let save = self.save();
        // Must be a single char followed (possibly after ws) by "to" then single char
        let c1 = match self.peek() {
            Some(c) if c.is_ascii_alphabetic() || c.is_ascii_digit() => c,
            _ => return Ok(None),
        };
        // Check char after c1
        let mut after_iter = self.src[self.pos + c1.len_utf8()..].chars();
        if let Some(ac) = after_iter.next() {
            if ac.is_ascii_alphanumeric() || ac == '_' { return Ok(None); }
        }
        self.pos += c1.len_utf8();
        self.skip_ws();
        if !self.try_keyword("to") { self.restore(save); return Ok(None); }
        self.skip_ws();
        let c2 = match self.peek() {
            Some(c) if c.is_ascii_alphabetic() || c.is_ascii_digit() => c,
            _ => { self.restore(save); return Ok(None); }
        };
        let mut after2 = self.src[self.pos + c2.len_utf8()..].chars();
        if let Some(ac) = after2.next() {
            if ac.is_ascii_alphanumeric() || ac == '_' { self.restore(save); return Ok(None); }
        }
        self.pos += c2.len_utf8();
        Ok(Some(Node::Range(c1, c2, for_negation)))
    }

    fn try_symbol(&mut self, for_negation: bool) -> Result<Option<Node>, Fail> {
        if self.peek() != Some('<') { return Ok(None); }
        let start = self.pos;
        self.pos += 1;
        let name_start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() || c == '_' { self.pos += c.len_utf8(); } else { break; }
        }
        if self.pos == name_start {
            self.record("symbol_identifier");
            return Err(Fail);
        }
        let name = self.src[name_start..self.pos].to_string();
        let sub = if self.starts("::") {
            self.pos += 2;
            let s2 = self.pos;
            while let Some(c) = self.peek() {
                if c.is_ascii_alphabetic() || c == '_' { self.pos += c.len_utf8(); } else { break; }
            }
            if self.pos == s2 { self.record("symbol_identifier"); return Err(Fail); }
            Some(self.src[s2..self.pos].to_string())
        } else { None };
        if !self.consume_str(">") {
            self.restore(start);
            return Ok(None);
        }

        if let Some(sub) = sub {
            if name != "category" {
                return Err(Fail);
            }
            let code = match crate::compiler::category_to_code(&sub) {
                Some(c) => c,
                None => {
                    // Semantic error; we need to propagate; use a flag
                    return Err(Fail);
                }
            };
            return Ok(Some(Node::Category(code.to_string(), for_negation)));
        }

        if let Some(s) = Symbol::from_name(&name) {
            return Ok(Some(Node::Symbol(s, for_negation)));
        }
        Err(Fail)
    }

    fn try_group(&mut self) -> Result<Option<Node>, Fail> {
        let save = self.save();
        if self.try_keyword("match") {
            self.skip_ws();
            let b = self.parse_block()?;
            return Ok(Some(Node::Group(GroupKind::Match, b)));
        }
        if self.try_keyword("either") {
            self.skip_ws();
            let b = self.parse_block()?;
            return Ok(Some(Node::Group(GroupKind::Either, b)));
        }
        if self.try_keyword("capture") {
            self.skip_ws();
            // optional identifier(s) before block
            if self.peek() == Some('{') {
                let b = self.parse_block()?;
                return Ok(Some(Node::Group(GroupKind::Capture(None), b)));
            }
            // Try to parse identifier. If failed, we still need to produce block-or-identifier error
            let first_start = self.pos;
            let first_end = self.parse_ident_bounds();
            if first_end == first_start {
                self.record_many(&["block", "identifier"]);
                return Err(Fail);
            }
            // name parts are concatenated with original whitespace
            let mut end = first_end;
            self.pos = first_end;
            loop {
                let s = self.save();
                self.skip_ws();
                match self.peek() {
                    Some(c) if c.is_ascii_alphabetic() || c == '_' => {
                        let new_end = self.parse_ident_bounds();
                        if new_end == self.pos { self.restore(s); break; }
                        end = new_end;
                        self.pos = new_end;
                    }
                    _ => { self.restore(s); break; }
                }
            }
            let name = self.src[first_start..end].to_string();
            self.skip_ws();
            let b = self.parse_block()?;
            return Ok(Some(Node::Group(GroupKind::Capture(Some(name)), b)));
        }
        self.restore(save);
        Ok(None)
    }

    fn parse_ident_bounds(&mut self) -> usize {
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() || c == '_' { self.pos += c.len_utf8(); } else { break; }
        }
        self.pos
    }

    fn try_assertion(&mut self) -> Result<Option<Node>, Fail> {
        if self.try_keyword("ahead") {
            self.skip_ws();
            let b = self.parse_block()?;
            return Ok(Some(Node::Assertion(AssertionKind::Ahead, b)));
        }
        if self.try_keyword("behind") {
            self.skip_ws();
            let b = self.parse_block()?;
            return Ok(Some(Node::Assertion(AssertionKind::Behind, b)));
        }
        Ok(None)
    }

    fn try_var_invocation(&mut self) -> Result<Option<Node>, Fail> {
        if self.peek() != Some('.') { return Ok(None); }
        let save = self.save();
        self.pos += 1;
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() || c == '_' { self.pos += c.len_utf8(); } else { break; }
        }
        if self.pos == start { self.restore(save); return Ok(None); }
        Ok(Some(Node::VarInvocation(self.src[start..self.pos].to_string())))
    }

    fn try_quantifier(&mut self) -> Result<Option<Quantifier>, Fail> {
        let save = self.save();
        if self.try_keyword("some") {
            self.skip_ws();
            if !self.try_keyword("of") { self.restore(save); return Ok(None); }
            return Ok(Some(Quantifier::Some_));
        }
        if self.try_keyword("any") {
            self.skip_ws();
            if !self.try_keyword("of") { self.restore(save); return Ok(None); }
            return Ok(Some(Quantifier::Any));
        }
        if self.try_keyword("option") {
            self.skip_ws();
            if !self.try_keyword("of") { self.restore(save); return Ok(None); }
            return Ok(Some(Quantifier::Option_));
        }
        if self.try_keyword("over") {
            self.skip_ws();
            let n = match self.try_integer() {
                Some(n) => n,
                None => { self.restore(save); return Ok(None); }
            };
            self.skip_ws();
            if !self.try_keyword("of") { self.restore(save); return Ok(None); }
            return Ok(Some(Quantifier::Over(n)));
        }
        // integer
        if let Some(n) = self.try_integer() {
            self.skip_ws();
            if self.try_keyword("to") {
                self.skip_ws();
                let m = match self.try_integer() {
                    Some(x) => x,
                    None => { self.record("amount"); return Err(Fail); }
                };
                self.skip_ws();
                if !self.try_keyword("of") { self.record("of"); return Err(Fail); }
                return Ok(Some(Quantifier::Range(n, m)));
            }
            if self.try_keyword("of") {
                return Ok(Some(Quantifier::Exact(n)));
            }
            self.restore(save);
            return Ok(None);
        }
        Ok(None)
    }

    fn try_integer(&mut self) -> Option<u64> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() { self.pos += c.len_utf8(); } else { break; }
        }
        if self.pos == start { return None; }
        self.src[start..self.pos].parse().ok()
    }
