//! Melody -> regex compiler

use crate::ast::*;
use crate::errfmt::Error;
use crate::parser::P;
use std::collections::HashMap;

pub fn compile(src: &str) -> Result<String, String> {
    let mut parser = P::new(src);
    let nodes = match parser.parse_root() {
        Ok(n) => n,
        Err(e) => return Err(e.format(src)),
    };
    let mut vars: HashMap<String, String> = HashMap::new();
    let mut out = String::new();
    for n in &nodes {
        match compile_node(n, &mut vars) {
            Ok(s) => out.push_str(&s),
            Err(e) => return Err(e),
        }
    }
    Ok(out)
}

fn compile_node(n: &Node, vars: &mut HashMap<String, String>) -> Result<String, String> {
    Ok(match n {
        Node::Literal(s) => escape_literal(s),
        Node::Raw(s) => s.clone(),
        Node::Symbol(sym, neg) => compile_symbol(sym, *neg)?,
        Node::Category(code, neg) => {
            if *neg { format!("\\P{{{}}}", code) } else { format!("\\p{{{}}}", code) }
        }
        Node::Range(from, to, neg) => {
            if *neg { format!("[^{}-{}]", from, to) } else { format!("[{}-{}]", from, to) }
        }
        Node::Quantifier(q, inner) => compile_quantifier(q, inner, vars)?,
        Node::Group(kind, body) => compile_group(kind, body, vars)?,
        Node::Assertion(kind, body) => compile_assertion(kind, body, vars)?,
        Node::VarInvocation(name) => {
            match vars.get(name) {
                Some(v) => v.clone(),
                None => return Err("usage of an uninitialized variable".to_string()),
            }
        }
        Node::VarDecl(name, body) => {
            let mut inner = String::new();
            for b in body { inner.push_str(&compile_node(b, vars)?); }
            vars.insert(name.clone(), inner);
            String::new()
        }
    })
}

fn compile_quantifier(q: &Quantifier, inner: &Node, vars: &mut HashMap<String, String>) -> Result<String, String> {
    // Semantic checks
    match inner {
        Node::Assertion(_, _) => return Err("unexpected assertion in quantifier".to_string()),
        Node::VarInvocation(_) => return Err("unexpected variable invocation in quantifier".to_string()),
        Node::Symbol(sym, _) => {
            if matches!(sym, Symbol::Start | Symbol::End | Symbol::Boundary) {
                // Hmm, but test showed `some of <boundary>; -> \b+` works.
                if matches!(sym, Symbol::Start | Symbol::End) {
                    return Err("unexpected special symbol in quantifier".to_string());
                }
            }
        }
        _ => {}
    }
    let body = compile_node(inner, vars)?;
    let suffix = match q {
        Quantifier::Exact(n) => format!("{{{}}}", n),
        Quantifier::Range(n, m) => {
            if m < n { return Err("usage of an invalid quantifier range".to_string()); }
            format!("{{{},{}}}", n, m)
        }
        Quantifier::Over(n) => format!("{{{},}}", n + 1),
        Quantifier::Some_ => "+".to_string(),
        Quantifier::Any => "*".to_string(),
        Quantifier::Option_ => "?".to_string(),
    };
    Ok(format!("{}{}", body, suffix))
}

fn compile_group(kind: &GroupKind, body: &[Node], vars: &mut HashMap<String, String>) -> Result<String, String> {
    let parts: Vec<String> = body.iter().map(|n| compile_node(n, vars)).collect::<Result<_, _>>()?;
    Ok(match kind {
        GroupKind::Match => format!("(?:{})", parts.join("")),
        GroupKind::Either => format!("(?:{})", parts.join("|")),
        GroupKind::Capture(None) => format!("({})", parts.join("")),
        GroupKind::Capture(Some(name)) => format!("(?<{}>{})", name, parts.join("")),
    })
}

fn compile_assertion(kind: &AssertionKind, body: &[Node], vars: &mut HashMap<String, String>) -> Result<String, String> {
    let parts: Vec<String> = body.iter().map(|n| compile_node(n, vars)).collect::<Result<_, _>>()?;
    let joined = parts.join("");
    Ok(match kind {
        AssertionKind::Ahead => format!("(?={})", joined),
        AssertionKind::Behind => format!("(?<={})", joined),
        AssertionKind::NotAhead => format!("(?!{})", joined),
        AssertionKind::NotBehind => format!("(?<!{})", joined),
    })
}

pub fn compile_symbol(sym: &Symbol, neg: bool) -> Result<String, String> {
    Ok(match (sym, neg) {
        (Symbol::Char, false) => ".".into(),
        (Symbol::Char, true) => return Err("negative char not allowed".into()),
        (Symbol::Start, true) => return Err("negative start not allowed".into()),
        (Symbol::End, true) => return Err("negative end not allowed".into()),
        (Symbol::Start, false) => "^".into(),
        (Symbol::End, false) => "$".into(),
        (Symbol::Space, false) => " ".into(),
        (Symbol::Space, true) => "[^ ]".into(),
        (Symbol::Whitespace, false) => "\\s".into(),
        (Symbol::Whitespace, true) => "\\S".into(),
        (Symbol::Digit, false) => "\\d".into(),
        (Symbol::Digit, true) => "\\D".into(),
        (Symbol::Word, false) => "\\w".into(),
        (Symbol::Word, true) => "\\W".into(),
        (Symbol::Newline, false) => "\\n".into(),
        (Symbol::Newline, true) => "[^\\n]".into(),
        (Symbol::Tab, false) => "\\t".into(),
        (Symbol::Tab, true) => "[^\\t]".into(),
        (Symbol::Return, false) => "\\r".into(),
        (Symbol::Return, true) => "[^\\r]".into(),
        (Symbol::Feed, false) => "\\f".into(),
        (Symbol::Feed, true) => "[^\\f]".into(),
        (Symbol::Null, false) => "\\0".into(),
        (Symbol::Null, true) => "[^\\0]".into(),
        (Symbol::Vertical, false) => "\\v".into(),
        (Symbol::Vertical, true) => "[^\\v]".into(),
        (Symbol::Backspace, false) => "[\\b]".into(),
        (Symbol::Backspace, true) => "[^\\b]".into(),
        (Symbol::Alphabetic, false) => "[a-zA-Z]".into(),
        (Symbol::Alphabetic, true) => "[^a-zA-Z]".into(),
        (Symbol::Alphanumeric, false) => "[a-zA-Z0-9]".into(),
        (Symbol::Alphanumeric, true) => "[^a-zA-Z0-9]".into(),
        (Symbol::Boundary, false) => "\\b".into(),
        (Symbol::Boundary, true) => "\\B".into(),
    })
}

