//! CLI argument parsing

pub struct Config {
    pub input_file: Option<String>,
    pub output_file: Option<String>,
    pub test: Option<String>,
    pub test_file: Option<String>,
    pub no_color: bool,
    pub repl: bool,
    pub gen_completions: Option<String>,
}

pub enum CliError {
    Help(String),
    Version(String),
    Msg(String, u8),
}

pub fn help_text(bin: &str) -> String {
    format!(r#"A CLI wrapping the Melody language compiler

Usage: {bin} [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version
"#, bin = bin)
}

pub fn parse(args: &[String], bin: &str) -> Result<Config, CliError> {
    let mut cfg = Config {
        input_file: None, output_file: None, test: None,
        test_file: None, no_color: false, repl: false, gen_completions: None,
    };
    let mut i = 0;
    // Track which options were set (to detect "cannot be used multiple times")
    let mut set_output = false;
    let mut set_no_color = false;
    let mut set_repl = false;
    let mut set_gen = false;
    let mut set_test = false;
    let mut set_testfile = false;
    let mut set_input = false;

    // We use a single-pass loop; help/version trigger immediate return.
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-h" | "--help" => return Err(CliError::Help(help_text(bin))),
            "-V" | "--version" => return Err(CliError::Version(format!("melody_cli {}", env!("CARGO_PKG_VERSION")))),
            "-o" | "--output" => {
                if set_output { return Err(clap_err_multi("--output <OUTPUT_FILE_PATH>", bin, &usage_for(&cfg, set_output, set_no_color, set_repl, set_gen, set_test, set_testfile, set_input, bin))); }
                let val = next_arg(args, &mut i, "--output <OUTPUT_FILE_PATH>", bin)?;
                cfg.output_file = Some(val);
                set_output = true;
            }
            "-n" | "--no-color" => {
                if set_no_color { return Err(clap_err_multi("--no-color", bin, &usage_for(&cfg, set_output, set_no_color, set_repl, set_gen, set_test, set_testfile, set_input, bin))); }
                cfg.no_color = true;
                set_no_color = true;
            }
            "-r" | "--repl" => {
                if set_repl { return Err(clap_err_multi("--repl", bin, &usage_for(&cfg, set_output, set_no_color, set_repl, set_gen, set_test, set_testfile, set_input, bin))); }
                cfg.repl = true;
                set_repl = true;
            }
            "--generate-completions" => {
                if set_gen { return Err(clap_err_multi("--generate-completions <completions>", bin, &usage_for(&cfg, set_output, set_no_color, set_repl, set_gen, set_test, set_testfile, set_input, bin))); }
                let val = next_arg(args, &mut i, "--generate-completions <completions>", bin)?;
                cfg.gen_completions = Some(val);
                set_gen = true;
            }
            "-t" | "--test" => {
                if set_test { return Err(clap_err_multi("--test <test>", bin, &usage_for(&cfg, set_output, set_no_color, set_repl, set_gen, set_test, set_testfile, set_input, bin))); }
                let val = next_arg(args, &mut i, "--test <test>", bin)?;
                cfg.test = Some(val);
                set_test = true;
            }
            "-f" | "--test-file" => {
                if set_testfile { return Err(clap_err_multi("--test-file <test-file>", bin, &usage_for(&cfg, set_output, set_no_color, set_repl, set_gen, set_test, set_testfile, set_input, bin))); }
                let val = next_arg(args, &mut i, "--test-file <test-file>", bin)?;
                cfg.test_file = Some(val);
                set_testfile = true;
            }
            other if other.starts_with('-') && other != "-" => {
                return Err(CliError::Msg(format!("error: unexpected argument '{}' found\n\nFor more information, try '--help'.", other), 2));
            }
            _ => {
                if cfg.input_file.is_some() {
                    return Err(CliError::Msg(format!("error: unexpected argument '{}' found\n\nFor more information, try '--help'.", a), 2));
                }
                cfg.input_file = Some(a.clone());
                set_input = true;
                i += 1;
                continue;
            }
        }
        i += 1;
    }

    // Conflict detection
    check_conflicts(&cfg, bin, set_output, set_no_color, set_repl, set_gen, set_test, set_testfile, set_input)?;

    Ok(cfg)
}

fn next_arg(args: &[String], i: &mut usize, name: &str, _bin: &str) -> Result<String, CliError> {
    if *i + 1 >= args.len() {
        return Err(CliError::Msg(format!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.", name), 2));
    }
    *i += 1;
    Ok(args[*i].clone())
}

fn clap_err_multi(arg: &str, _bin: &str, usage: &str) -> CliError {
    CliError::Msg(
        format!("error: the argument '{}' cannot be used multiple times\n\n{}\n\nFor more information, try '--help'.", arg, usage),
        2
    )
}

fn usage_for(cfg: &Config, _o: bool, no_color: bool, repl: bool, gen: bool, test: bool, tf: bool, input: bool, bin: &str) -> String {
    // Approximate Usage line; this is what clap generates based on provided args so far.
    let mut parts = vec![format!("Usage: {}", bin)];
    if no_color { parts.push(" --no-color".to_string()); }
    if let Some(ref p) = cfg.output_file { let _ = p; parts.push(" --output <OUTPUT_FILE_PATH>".to_string()); }
    if repl { parts.push(" --repl".to_string()); }
    if gen { parts.push(" --generate-completions <completions>".to_string()); }
    if test { parts.push(" --test <test>".to_string()); }
    if tf { parts.push(" --test-file <test-file>".to_string()); }
    if parts.len() == 1 {
        parts.push(" [OPTIONS]".to_string());
    }
    // Input file
    if input {
        parts.push(" <INPUT_FILE_PATH>".to_string());
    } else {
        parts.push(" [INPUT_FILE_PATH]".to_string());
    }
    parts.concat()
}

fn check_conflicts(cfg: &Config, bin: &str, o: bool, nc: bool, r: bool, g: bool, t: bool, tf: bool, inp: bool) -> Result<(), CliError> {
    // --test/--test-file/--output/--generate-completions/--repl conflict pairs
    let conflicts: &[(bool, &str, bool, &str)] = &[
        (g, "--generate-completions <completions>", t, "--test <test>"),
        (g, "--generate-completions <completions>", tf, "--test-file <test-file>"),
        (g, "--generate-completions <completions>", o, "--output <OUTPUT_FILE_PATH>"),
        (g, "--generate-completions <completions>", r, "--repl"),
        (r, "--repl", t, "--test <test>"),
        (r, "--repl", tf, "--test-file <test-file>"),
        (r, "--repl", o, "--output <OUTPUT_FILE_PATH>"),
        (o, "--output <OUTPUT_FILE_PATH>", t, "--test <test>"),
        (o, "--output <OUTPUT_FILE_PATH>", tf, "--test-file <test-file>"),
        (t, "--test <test>", tf, "--test-file <test-file>"),
    ];
    for &(a_set, a_name, b_set, b_name) in conflicts {
        if a_set && b_set {
            // Clap-style error message
            let usage = usage_for(cfg, o, nc, r, g, t, tf, inp, bin);
            return Err(CliError::Msg(
                format!("error: the argument '{}' cannot be used with '{}'\n\n{}\n\nFor more information, try '--help'.", a_name, b_name, usage), 2));
        }
    }
    Ok(())
}
