//! Simple REPL

use std::io::{self, Write, BufRead};
use std::process::ExitCode;

pub fn run(color: bool) -> ExitCode {
    print_banner();
    let stdin = io::stdin();
    let mut reader = stdin.lock();
    let mut lines: Vec<String> = Vec::new();
    let mut undone: Vec<String> = Vec::new();

    loop {
        if color { print!("\n\x1b[2m~\x1b[0m "); } else { print!("\n~ "); }
        io::stdout().flush().ok();
        let mut buf = String::new();
        let n = match reader.read_line(&mut buf) {
            Ok(n) => n,
            Err(_) => return ExitCode::from(1),
        };
        if n == 0 { return ExitCode::SUCCESS; }
        let line = buf.trim_end_matches(['\n', '\r']).to_string();
        if let Some(cmd) = line.strip_prefix(':') {
            match cmd {
                "u" | "undo" => {
                    if lines.is_empty() {
                        println!("nothing to undo");
                    } else {
                        let x = lines.pop().unwrap();
                        undone.push(x);
                        println!("undo");
                        let src = lines.join("\n");
                        match crate::compiler::compile(&src) {
                            Ok(r) => print_regex(&r, color),
                            Err(_) => {}
                        }
                    }
                }
                "r" | "redo" => {
                    if undone.is_empty() {
                        println!("nothing to redo");
                    } else {
                        let x = undone.pop().unwrap();
                        lines.push(x);
                        println!("redo");
                        let src = lines.join("\n");
                        match crate::compiler::compile(&src) {
                            Ok(r) => print_regex(&r, color),
                            Err(_) => {}
                        }
                    }
                }
                "c" | "clear" => {
                    lines.clear();
                    undone.clear();
                    println!("clear");
                }
                "s" | "source" => {
                    if lines.is_empty() { println!("no lines to print"); }
                    else {
                        println!("source");
                        for (i, l) in lines.iter().enumerate() {
                            println!("{} {}", i+1, l);
                        }
                    }
                }
                "e" | "exit" => return ExitCode::SUCCESS,
                other => {
                    println!("unknown command: {}", other);
                }
            }
            continue;
        }
        // Not a command. Try compiling with appended line.
        let trial: Vec<String> = lines.iter().cloned().chain(std::iter::once(line.clone())).collect();
        let src = trial.join("\n");
        match crate::compiler::compile(&src) {
            Ok(r) => {
                lines.push(line);
                undone.clear();
                print_regex(&r, color);
            }
            Err(e) => {
                if color {
                    eprintln!("\x1b[91mError: {}\x1b[0m", e);
                } else {
                    eprintln!("Error: {}", e);
                }
            }
        }
    }
}

fn print_regex(s: &str, color: bool) {
    if color { println!("\x1b[94m{}\x1b[0m", s); }
    else { println!("{}", s); }
}

fn print_banner() {
    println!("Melody REPL v{}", env!("CARGO_PKG_VERSION"));
    println!();
    println!("Commands:");
    println!();
    println!("- :u, :undo - undo the latest line");
    println!("- :r, :redo - redo the latest undo");
    println!("- :c, :clear - clear all REPL history and previous input");
    println!("- :s, :source - print all previously entered lines");
    println!("- :e, :exit - exit the REPL");
}
