mod ast;
mod parser;
mod compiler;
mod cli;
mod repl;
mod errfmt;

use std::io::{self, Read, IsTerminal};
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    let argv0 = args.get(0).cloned().unwrap_or_else(|| "melody".into());
    let bin_name = std::path::Path::new(&argv0)
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("melody")
        .to_string();

    let cfg = match cli::parse(&args[1..], &bin_name) {
        Ok(c) => c,
        Err(cli::CliError::Help(s)) => { print!("{}", s); return ExitCode::SUCCESS; }
        Err(cli::CliError::Version(s)) => { println!("{}", s); return ExitCode::SUCCESS; }
        Err(cli::CliError::Msg(s, code)) => { eprintln!("{}", s); return ExitCode::from(code); }
    };

    if let Some(shell) = cfg.gen_completions.as_deref() {
        return match shell {
            "bash" => { print!("{}", include_str!("completions/bash.sh")); ExitCode::SUCCESS }
            "zsh" => { print!("{}", include_str!("completions/zsh.sh")); ExitCode::SUCCESS }
            "fish" => { print!("{}", include_str!("completions/fish.sh")); ExitCode::SUCCESS }
            "elvish" => { print!("{}", include_str!("completions/elvish.sh")); ExitCode::SUCCESS }
            "powershell" => { print!("{}", include_str!("completions/powershell.sh")); ExitCode::SUCCESS }
            _ => {
                eprintln!("Unknown or unsupported shell: '{}'", shell);
                eprintln!("Try one of: 'bash', 'zsh', 'fish', 'elvish', 'powershell'");
                eprintln!();
                ExitCode::SUCCESS
            }
        };
    }

    let stdin_tty = io::stdin().is_terminal();
    let stdout_tty = io::stdout().is_terminal();
    let stderr_tty = io::stderr().is_terminal();
    let use_color = !cfg.no_color;

    if cfg.repl {
        if !stdin_tty || !stdout_tty {
            eprintln!("Error: repl argument supplied with piped input or output");
            return ExitCode::from(65);
        }
        return repl::run(use_color && stdout_tty);
    }

    let input = match cfg.input_file.as_deref() {
        Some("-") => {
            let mut s = String::new();
            if io::stdin().read_to_string(&mut s).is_err() {
                eprintln!("Error reading stdin");
                return ExitCode::from(66);
            }
            s
        }
        Some(path) => match std::fs::read_to_string(path) {
            Ok(s) => s,
            Err(e) => {
                if use_color && stderr_tty {
                    eprintln!("\x1b[91mError: {}\x1b[0m", e);
                } else {
                    eprintln!("Error: {}", e);
                }
                return ExitCode::from(66);
            }
        },
        None => {
            if !stdin_tty {
                let mut s = String::new();
                if io::stdin().read_to_string(&mut s).is_err() {
                    eprintln!("Error reading stdin");
                    return ExitCode::from(66);
                }
                s
            } else {
                let msg = "No input file supplied and no input piped\nTry adding a path argument: 'melody ./file.mdy'";
                if use_color && stderr_tty {
                    eprintln!("\x1b[94m{}\x1b[0m", msg);
                } else {
                    eprintln!("{}", msg);
                }
                eprintln!();
                eprint!("{}", cli::help_text(&bin_name));
                return ExitCode::SUCCESS;
            }
        }
    };

    match compiler::compile(&input) {
        Ok(regex) => {
            if let Some(test_str) = &cfg.test {
                print_test_str(&regex, test_str, use_color, stdout_tty);
            } else if let Some(tf) = &cfg.test_file {
                match std::fs::read_to_string(tf) {
                    Ok(content) => print_test_file(&regex, tf, &content, use_color, stdout_tty),
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        return ExitCode::from(66);
                    }
                }
            } else if let Some(out_path) = &cfg.output_file {
                if let Err(e) = std::fs::write(out_path, &regex) {
                    eprintln!("Error: {}", e);
                    return ExitCode::from(66);
                }
            } else {
                if use_color && stdout_tty {
                    println!("\x1b[94m{}\x1b[0m", regex);
                } else {
                    println!("{}", regex);
                }
            }
            ExitCode::SUCCESS
        }
        Err(e) => {
            if use_color && stderr_tty {
                eprintln!("\x1b[91mError: {}\x1b[0m", e);
            } else {
                eprintln!("Error: {}", e);
            }
            ExitCode::from(65)
        }
    }
}

fn print_test_str(regex: &str, input: &str, color: bool, tty: bool) {
    let matched = match regex_test::matches(regex, input) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: regex compilation failed: {}", e);
            return;
        }
    };
    let mut disp: String = input.chars().take(10).collect();
    if input.chars().count() > 10 { disp.push_str("..."); }
    if color && tty {
        let c = if matched { "\x1b[92m" } else { "\x1b[91m" };
        let w = if matched { "matched" } else { "did not match" };
        println!("'{}' {}{}\x1b[0m", disp, c, w);
    } else {
        println!("'{}' {}", disp, if matched { "matched" } else { "did not match" });
    }
}

fn print_test_file(regex: &str, path: &str, content: &str, color: bool, tty: bool) {
    let matched = match regex_test::matches(regex, content) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: regex compilation failed: {}", e);
            return;
        }
    };
    if color && tty {
        let c = if matched { "\x1b[92m" } else { "\x1b[91m" };
        let w = if matched { "matched" } else { "did not match" };
        println!("{} {}{}\x1b[0m", path, c, w);
    } else {
        println!("{} {}", path, if matched { "matched" } else { "did not match" });
    }
}

mod regex_test {
    use std::process::{Command, Stdio};
    use std::io::Write;
    pub fn matches(regex: &str, input: &str) -> Result<bool, String> {
        let script = r#"
import sys, re
try:
    r = re.compile(sys.argv[1])
except re.error as e:
    sys.stderr.write(str(e))
    sys.exit(2)
m = r.search(sys.stdin.read())
sys.exit(0 if m else 1)
"#;
        let mut child = match Command::new("python3")
            .arg("-c").arg(script).arg(regex)
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(Stdio::piped())
            .spawn() {
            Ok(c) => c,
            Err(e) => return Err(e.to_string()),
        };
        if let Some(mut stdin) = child.stdin.take() {
            let _ = stdin.write_all(input.as_bytes());
        }
        let out = match child.wait_with_output() {
            Ok(o) => o,
            Err(e) => return Err(e.to_string()),
        };
        match out.status.code() {
            Some(0) => Ok(true),
            Some(1) => Ok(false),
            _ => Err(String::from_utf8_lossy(&out.stderr).to_string()),
        }
    }
}
