fn is_single_atom(s: &str) -> bool {
    let bytes = s.as_bytes();
    let len = bytes.len();
    if len == 0 { return false; }
    if len == 1 { return true; }
    // Simple escape: "\X" — 2-byte ASCII `\` followed by a single byte
    if len == 2 && bytes[0] == b'\\' { return true; }
