//! CLI parser matching clap v4-style output

#[derive(Default)]
pub struct Config {
    pub input_file: Option<String>,
    pub output_file: Option<String>,
    pub test: Option<String>,
    pub test_file: Option<String>,
    pub no_color: bool,
    pub repl: bool,
    pub gen_completions: Option<String>,
}

pub enum CliError {
    Help(String),
    Version(String),
    Msg(String, u8),
}

pub fn help_text(bin: &str) -> String {
    format!(r#"A CLI wrapping the Melody language compiler

Usage: {bin} [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version
"#, bin = bin)
}

/// Identifier for each flag (used for conflict tracking and naming)
#[derive(Copy, Clone, PartialEq)]
enum Flag {
    Output, NoColor, Repl, Gen, Test, TestFile,
}

impl Flag {
    fn display(self) -> &'static str {
        match self {
            Flag::Output => "--output <OUTPUT_FILE_PATH>",
            Flag::NoColor => "--no-color",
            Flag::Repl => "--repl",
            Flag::Gen => "--generate-completions <completions>",
            Flag::Test => "--test <test>",
            Flag::TestFile => "--test-file <test-file>",
        }
    }
    fn conflicts_with(self, other: Flag) -> bool {
        use Flag::*;
        let pair = (self, other);
        matches!(pair,
            (Output, Test) | (Test, Output) |
            (Output, TestFile) | (TestFile, Output) |
            (Output, Gen) | (Gen, Output) |
            (Test, TestFile) | (TestFile, Test) |
            (Test, Gen) | (Gen, Test) |
            (Test, Repl) | (Repl, Test) |
            (TestFile, Gen) | (Gen, TestFile) |
            (TestFile, Repl) | (Repl, TestFile) |
            (Repl, Gen) | (Gen, Repl)
        )
    }
}

pub fn parse(args: &[String], bin: &str) -> Result<Config, CliError> {
    let mut cfg = Config::default();
    let mut first_flag: Option<Flag> = None; // for conflict Usage line
    let mut set_flags: Vec<Flag> = Vec::new();
    let mut i = 0;

    let check_add = |flag: Flag, cfg: &Config, first_flag: &mut Option<Flag>, set_flags: &mut Vec<Flag>, bin: &str| -> Result<(), CliError> {
        // Check for duplicate
        if set_flags.contains(&flag) {
            // Multiple times
            return Err(CliError::Msg(format!(
                "error: the argument '{}' cannot be used multiple times\n\nUsage: {} [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.",
                flag.display(), bin
            ), 2));
        }
        // Check conflicts with earlier flags
        for &f in set_flags.iter() {
            if flag.conflicts_with(f) {
                let usage_flag = *first_flag;
                let usage = if let Some(uf) = usage_flag {
                    format!("Usage: {} {} [INPUT_FILE_PATH]", bin, uf.display())
                } else {
                    format!("Usage: {} [OPTIONS] [INPUT_FILE_PATH]", bin)
                };
                return Err(CliError::Msg(format!(
                    "error: the argument '{}' cannot be used with '{}'\n\n{}\n\nFor more information, try '--help'.",
                    flag.display(), f.display(), usage
                ), 2));
            }
        }
        set_flags.push(flag);
        if first_flag.is_none() {
            *first_flag = Some(flag);
        }
        let _ = cfg;
        Ok(())
    };

    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-h" | "--help" => return Err(CliError::Help(help_text(bin))),
            "-V" | "--version" => return Err(CliError::Version(format!("melody_cli {}", env!("CARGO_PKG_VERSION")))),
            "-o" | "--output" => {
                check_add(Flag::Output, &cfg, &mut first_flag, &mut set_flags, bin)?;
                let val = next_arg(args, &mut i, Flag::Output.display(), bin)?;
                cfg.output_file = Some(val);
            }
            "-n" | "--no-color" => {
                check_add(Flag::NoColor, &cfg, &mut first_flag, &mut set_flags, bin)?;
                cfg.no_color = true;
            }
            "-r" | "--repl" => {
                check_add(Flag::Repl, &cfg, &mut first_flag, &mut set_flags, bin)?;
                cfg.repl = true;
            }
            "--generate-completions" => {
                check_add(Flag::Gen, &cfg, &mut first_flag, &mut set_flags, bin)?;
                let val = next_arg(args, &mut i, Flag::Gen.display(), bin)?;
                cfg.gen_completions = Some(val);
            }
            "-t" | "--test" => {
                check_add(Flag::Test, &cfg, &mut first_flag, &mut set_flags, bin)?;
                let val = next_arg(args, &mut i, Flag::Test.display(), bin)?;
                cfg.test = Some(val);
            }
            "-f" | "--test-file" => {
                check_add(Flag::TestFile, &cfg, &mut first_flag, &mut set_flags, bin)?;
                let val = next_arg(args, &mut i, Flag::TestFile.display(), bin)?;
                cfg.test_file = Some(val);
            }
            other if other.starts_with('-') && other != "-" => {
                return Err(CliError::Msg(format!(
                    "error: unexpected argument '{}' found\n\nUsage: {} [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.",
                    other, bin
                ), 2));
            }
            _ => {
                if cfg.input_file.is_some() {
                    return Err(CliError::Msg(format!(
                        "error: unexpected argument '{}' found\n\nUsage: {} [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.",
                        a, bin
                    ), 2));
                }
                cfg.input_file = Some(a.clone());
                i += 1;
                continue;
            }
        }
        i += 1;
    }
    Ok(cfg)
}

fn next_arg(args: &[String], i: &mut usize, name: &str, _bin: &str) -> Result<String, CliError> {
    if *i + 1 >= args.len() {
        return Err(CliError::Msg(format!(
            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.",
            name
        ), 2));
    }
    *i += 1;
    Ok(args[*i].clone())
}
EOF
