            Flag::Gen => "--generate-completions <completions>",
            Flag::Test => "--test <test>",
            Flag::TestFile => "--test-file <test-file>",
        }
    }
    fn conflicts_with(self, other: Flag) -> bool {
        use Flag::*;
        let pair = (self, other);
        matches!(pair,
