}

pub fn parse(args: &[String], bin: &str) -> Result<Config, CliError> {
    let mut cfg = Config::default();
    let mut first_flag: Option<Flag> = None; // for conflict Usage line
    let mut set_flags: Vec<Flag> = Vec::new();
