                let val = opt_value(args, &mut i, value, Flag::Gen.display(), bin)?;
                cfg.gen_completions = Some(val);
            }
            "-t" | "--test" => {
                check_add(Flag::Test, &cfg, &mut first_flag, &mut set_flags, bin)?;
                let val = opt_value(args, &mut i, value, Flag::Test.display(), bin)?;
                cfg.test = Some(val);
            }
            "-f" | "--test-file" => {
                check_add(Flag::TestFile, &cfg, &mut first_flag, &mut set_flags, bin)?;
                let val = opt_value(args, &mut i, value, Flag::TestFile.display(), bin)?;
                cfg.test_file = Some(val);
            }
            other if other.starts_with('-') && other != "-" => {
                return Err(CliError::Msg(format!(
                    "error: unexpected argument '{}' found\\n\\nUsage: {} [OPTIONS] [INPUT_FILE_PATH]\\n\\nFor more information, try '--help'.",
                    other, bin
                ), 2));
            }
            _ => {
                if cfg.input_file.is_some() {
                    return Err(CliError::Msg(format!(
                        "error: unexpected argument '{}' found\\n\\nUsage: {} [OPTIONS] [INPUT_FILE_PATH]\\n\\nFor more information, try '--help'.",
                        a, bin
                    ), 2));
                }
                cfg.input_file = Some(a.clone());
                i += 1;
                continue;
            }
        }
        i += 1;
    }
